// 5 - One Shape for Either Store, Email Must Match
// Shopify and WooCommerce answer in different shapes. This turns either one into the same fields,
// and an order is only described when the email on it matches the email the shopper typed.
const cfg = $('0 - Config: Your Settings').first().json;
const ask = $('2 - Claude Sorts It: Order Status, Product Question or a Person').first().json.output || {};
const platform = String(cfg.store_platform || '').trim().toLowerCase();
const typedEmail = String(ask.email || '').trim().toLowerCase();
const typedNumber = String(ask.order_number || '').replace(/[^0-9A-Za-z-]/g, '');
const shipWithin = Number(cfg.ship_within_days);
const daysSince = (iso) => Math.floor((Date.now() - new Date(iso).getTime()) / 86400000);

const out = {
  platform,
  intent: ask.intent || 'other',
  wants_person: ask.wants_person === true,
  handoff_reason: ask.handoff_reason || '',
  shopper_email: typedEmail,
  order_number: typedNumber,
  order_found: false,
  email_matches: false,
  order: null,
  products: [],
  late: false,
};
const lookedUp = ['order_status', 'product_question'].includes(out.intent);

if (lookedUp && platform === 'shopify') {
  const data = $('4a - Shopify: Look Up the Order or the Product').first().json.data || {};
  const o = ((data.orders || {}).nodes || [])[0];
  if (out.intent === 'order_status' && o) {
    out.order_found = true;
    out.email_matches = typedEmail !== '' && String(o.email || '').toLowerCase() === typedEmail;
    if (out.email_matches) {
      const tracking = (o.fulfillments || []).flatMap((f) => (f.trackingInfo || []).map((t) => ({ carrier: t.company, number: t.number, url: t.url, eta: f.estimatedDeliveryAt || '' })));
      out.order = {
        number: o.name,
        placed_at: o.createdAt,
        days_since_order: daysSince(o.createdAt),
        payment: o.displayFinancialStatus,
        fulfillment: o.displayFulfillmentStatus,
        items: ((o.lineItems || {}).nodes || []).map((li) => li.quantity + ' x ' + li.title),
        tracking,
      };
    }
  }
  if (out.intent === 'product_question') {
    out.products = ((data.products || {}).nodes || []).map((p) => ({
      title: p.title,
      url: p.onlineStoreUrl || '',
      price: p.priceRangeV2 ? p.priceRangeV2.minVariantPrice.amount + ' ' + p.priceRangeV2.minVariantPrice.currencyCode : '',
      in_stock: (p.totalInventory || 0) > 0,
      options: ((p.variants || {}).nodes || []).map((v) => v.title + (v.availableForSale ? '' : ' (sold out)')),
    }));
  }
}

if (lookedUp && platform === 'woocommerce') {
  const rows = $('4b - WooCommerce: Look Up the Order or the Product').all().map((i) => i.json).filter((r) => r && r.id);
  if (out.intent === 'order_status') {
    const o = rows.find((r) => String(r.number) === typedNumber);
    if (o) {
      out.order_found = true;
      out.email_matches = typedEmail !== '' && String((o.billing || {}).email || '').toLowerCase() === typedEmail;
      if (out.email_matches) {
        // Tracking sits in order meta when a shipment tracking plugin is installed.
        const meta = (o.meta_data || []).find((m) => m.key === '_wc_shipment_tracking_items');
        const tracking = ((meta && meta.value) || []).map((t) => ({ carrier: t.tracking_provider || t.custom_tracking_provider || '', number: t.tracking_number, url: t.custom_tracking_link || '', eta: '' }));
        out.order = {
          number: '#' + o.number,
          placed_at: o.date_created_gmt + 'Z',
          days_since_order: daysSince(o.date_created_gmt + 'Z'),
          payment: o.date_paid_gmt ? 'PAID' : 'UNPAID',
          fulfillment: o.status,
          items: (o.line_items || []).map((li) => li.quantity + ' x ' + li.name),
          tracking,
        };
      }
    }
  }
  if (out.intent === 'product_question') {
    out.products = rows.map((p) => ({ title: p.name, url: p.permalink, price: p.price, in_stock: p.stock_status === 'instock', options: [] }));
  }
}

// Your part 2: an order still unshipped past your shipping promise gets flagged.
const waiting = ['UNFULFILLED', 'PARTIALLY_FULFILLED', 'IN_PROGRESS', 'ON_HOLD', 'processing', 'on-hold'];
out.late = !!out.order && waiting.includes(out.order.fulfillment) && Number.isFinite(shipWithin) && out.order.days_since_order > shipWithin;

return [{ json: out }];

